+ }
+
+ g_clip_c2s.total_bytes =
+ (g_clip_c2s.data == NULL) ? 0 : g_strlen(g_clip_c2s.data);
+ g_clip_c2s.read_bytes_done = g_clip_c2s.total_bytes;
