+ field[value] = fieldValue
+ }
+
+ @Suppress("UNCHECKED_CAST") // We require that field's values are of type T.
+ fun write(writer: JsonWriter, value: Any?) {
+ val fieldValue = field[value] as T
+ adapter.toJson(writer, fieldValue)
+ }
+ }
